/**
 * @summary Capture a "Request a demo" / trial-request lead
 */
export const getCreateLeadUrl = () => {
  return `/tis-api/leads`;
};

export const createLead = async (
  leadInput: LeadInput,
  options?: RequestInit,
): Promise<LeadCreated> => {
  return customFetch<LeadCreated>(getCreateLeadUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(leadInput),
  });
};

export const getCreateLeadMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createLead>>,
    TError,
    { data: BodyType<LeadInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createLead>>,
  TError,
  { data: BodyType<LeadInput> },
  TContext
> => {
  const mutationKey = ["createLead"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createLead>>,
    { data: BodyType<LeadInput> }
  > = (props) => {
    const { data } = props ?? {};

    return createLead(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateLeadMutationResult = NonNullable<
  Awaited<ReturnType<typeof createLead>>
>;
export type CreateLeadMutationBody = BodyType<LeadInput>;
export type CreateLeadMutationError = ErrorType<ErrorResponse>;

/**
 * @summary Capture a "Request a demo" / trial-request lead
 */
export const useCreateLead = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createLead>>,
    TError,
    { data: BodyType<LeadInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof createLead>>,
  TError,
  { data: BodyType<LeadInput> },
  TContext
> => {
  return useMutation(getCreateLeadMutationOptions(options));
};
